import sys, os; sys.path.insert(0,'/home/claude/skripty')
from stranka import zapis
O='/home/claude/dokuio.com/src/obsah/gr/'
P=lambda n,p:{'nazev':n,'popis':p}
K3=[('Συμπληρώστε τα στοιχεία','Ό,τι δεν ξέρετε, παραλείψτε το – μένει γραμμή για συμπλήρωση με το χέρι.'),('Ελέγξτε το κείμενο','Κάθε παράγραφο μπορείτε να την αλλάξετε.'),('Κατεβάστε και υπογράψτε','PDF ή Word, δωρεάν.')]
PRIV=('Αποθηκεύετε τα στοιχεία μου;','Όχι. Το έγγραφο δημιουργείται απευθείας στον browser σας, τα στοιχεία δεν αποστέλλονται σε διακομιστή.')
AK='Το υπόδειγμα βασίζεται στις διατάξεις του Αστικού Κώδικα.'
def d(slug, ident, nazev, nazevA, popis, kat, il, slova, title, desc, perex, obsahPopis, obsah, online, hodi, nehodi, po, faq, zakony, vt, vd):
    landing={'title':title,'description':desc,'perex':perex,'obsahPopis':obsahPopis,'obsah':[P(*x) for x in obsah],'kroky':[P(*x) for x in K3],'online':online,'hodiSe':hodi,'nehodiSe':nehodi,'po':[P(*x) for x in po],'faq':[{'q':q,'a':a} for q,a in faq+[PRIV]],'zakony':zakony,'souvisejiciPopis':'Άλλα έγγραφα, επίσης δωρεάν.'}
    if not 70<=len(desc)<=170: print('DESC',slug,len(desc))
    if len(title.replace('{rok}','2026'))>70: print('TITLE',slug,len(title.replace('{rok}','2026')))
    if not 30<=len(vd)<=170: print('VD',slug,len(vd))
    if len(vt)>70: print('VT',slug,len(vt))
    for w in ('υπόδειγμα','PDF','δωρεάν'): assert w in title, (slug,w)
    zapis(O+slug+'.ts','gr',slug,ident,nazev,nazevA,{'popis':popis,'kategorie':kat,'ilustrace':il,'slova':slova},kat,landing,{'title':vt,'description':vd,'podnadpis':'Δωρεάν · αποτέλεσμα σε PDF και Word · διαρκεί λίγα λεπτά'})

